# --- DPI awareness (must be before any WinForms loading) ---------------------
# Add-Type -TypeDefinition 'using System.Runtime.InteropServices; public class DpiAware { [DllImport("user32.dll")] public static extern bool SetProcessDPIAware(); }' -ErrorAction SilentlyContinue
# try { [DpiAware]::SetProcessDPIAware() } catch {} # Disabled — native OS bitmap scaling preferred on HiDPI

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

$script:FFmpegPath        = $null
$script:FFprobePath       = $null
$script:CancelRequested   = $false
$script:CurrentFFmpegProc = $null
$script:IsProcessing      = $false
$script:SourceFiles       = @()    # [System.IO.FileInfo[]] — all files to process
$script:SourceFolderRoot  = $null  # string — set when folder was browsed/dropped
$script:VideoExtensions   = @(".mp4",".mov",".avi",".webm",".mkv",".mxf",".m4v",".wmv")
$script:Mode              = "Video"  # "Video" | "Audio"
$script:GpuMode          = "Auto"     # "Auto"|"CPU"|"NVIDIA"|"AMD"|"Intel"
$script:Codec            = "H.264"    # "H.264"|"H.265"
$script:ScaleAlgo        = "bicubic"  # "bicubic"|"lanczos"|"bilinear"
$script:Threads          = 0          # 0 = auto
$script:PlaySoundOnDone  = $true
$script:OpenFolderOnDone = $false
$script:AdvancedVisible  = $false

# --- Font embedding (Cormorant Garamond + Raleway) ---------------------------
# Fonts decoded from Base64 to %TEMP%, loaded via PrivateFontCollection.
# Fallback: Georgia (title), Segoe UI (labels/buttons), Consolas (log).

$script:FontCollection = $null
$script:FontCormorant  = $null
$script:FontRaleway    = $null
$script:FontTempFiles  = @()

function Initialize-EmbeddedFonts {
    $fonts = @{
        CormorantGaramond = ""
        RalewayRegular    = ""
        RalewayMedium     = ""
    }

    try {
        $script:FontCollection = New-Object Drawing.Text.PrivateFontCollection
        $fontDir = Join-Path $env:TEMP "ChuCha_Fonts"
        if (-not (Test-Path $fontDir)) { New-Item -ItemType Directory -Path $fontDir -Force | Out-Null }

        foreach ($name in $fonts.Keys) {
            $bytes = [Convert]::FromBase64String($fonts[$name])
            $tmpFile = Join-Path $fontDir "chucha_${name}.ttf"
            [IO.File]::WriteAllBytes($tmpFile, $bytes)
            $script:FontTempFiles += $tmpFile
            $script:FontCollection.AddFontFile($tmpFile)
        }

        foreach ($fam in $script:FontCollection.Families) {
            if ($fam.Name -like "*Cormorant*") { $script:FontCormorant = $fam }
            if ($fam.Name -like "*Raleway*")   { $script:FontRaleway   = $fam }
        }
    } catch {
        $script:FontCormorant = $null
        $script:FontRaleway   = $null
    }
}

function Remove-EmbeddedFontFiles {
    foreach ($f in $script:FontTempFiles) {
        Remove-Item $f -Force -ErrorAction SilentlyContinue
    }
}

Initialize-EmbeddedFonts

# --- Modern file picker (IFileOpenDialog COM) ---------------------------------
try {
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;

public static class ModernPicker {
    [DllImport("ole32.dll")]
    static extern int CoCreateInstance(
        ref Guid clsid, IntPtr outer, uint ctx, ref Guid iid, out IntPtr ppv);

    static readonly Guid CLSID_FileOpenDialog =
        new Guid("DC1C5A9C-E88A-4dde-A5A1-60F82A20AEF7");
    static readonly Guid IID_IFileOpenDialog =
        new Guid("d57c7288-d4ad-4768-be02-9d969532d960");

    const uint FOS_PICKFOLDERS      = 0x00000020;
    const uint FOS_FORCEFILESYSTEM  = 0x00000040;
    const uint FOS_ALLOWMULTISELECT = 0x00000200;

    [ComImport, Guid("d57c7288-d4ad-4768-be02-9d969532d960"),
     InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    interface IFileOpenDialog {
        [PreserveSig] int Show(IntPtr hwnd);
        void SetFileTypes(uint cTypes, IntPtr rgSpec);
        void SetFileTypeIndex(uint iIndex);
        void GetFileTypeIndex(out uint piIndex);
        void Advise(IntPtr pEvents, out uint pdwCookie);
        void Unadvise(uint dwCookie);
        void SetOptions(uint fos);
        void GetOptions(out uint pfos);
        void SetDefaultFolder(IntPtr psi);
        void SetFolder(IntPtr psi);
        void GetFolder(out IntPtr ppsi);
        void GetCurrentSelection(out IntPtr ppsi);
        void SetFileName([MarshalAs(UnmanagedType.LPWStr)] string pszName);
        void GetFileName(out IntPtr pszName);
        void SetTitle([MarshalAs(UnmanagedType.LPWStr)] string pszTitle);
        void SetOkButtonLabel([MarshalAs(UnmanagedType.LPWStr)] string pszText);
        void SetFileNameLabel([MarshalAs(UnmanagedType.LPWStr)] string pszLabel);
        void GetResult(out IntPtr ppsi);
        void AddPlace(IntPtr psi, int fdap);
        void SetDefaultExtension([MarshalAs(UnmanagedType.LPWStr)] string pszExt);
        void Close(int hr);
        void SetClientGuid(ref Guid guid);
        void ClearClientData();
        void SetFilter(IntPtr pFilter);
        void GetResults(out IntPtr ppenum);
        void GetSelectedItems(out IntPtr ppsai);
    }

    [ComImport, Guid("43826D1E-E718-42EE-BC55-A1E261C37BFE"),
     InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    interface IShellItem {
        void BindToHandler(IntPtr pbc, ref Guid bhid, ref Guid riid, out IntPtr ppv);
        void GetParent(out IntPtr ppsi);
        void GetDisplayName(uint sigdnName, out IntPtr ppszName);
        void GetAttributes(uint sfgaoMask, out uint psfgaoAttribs);
        void Compare(IntPtr psi, uint hint, out int piOrder);
    }

    [ComImport, Guid("b63ea76d-1f85-456f-a19c-48159efa858b"),
     InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    interface IShellItemArray {
        void BindToHandler(IntPtr pbc, ref Guid bhid, ref Guid riid, out IntPtr ppv);
        void GetPropertyStore(int flags, ref Guid riid, out IntPtr ppv);
        void GetPropertyDescriptionList(IntPtr keyType, ref Guid riid, out IntPtr ppv);
        void GetAttributes(int attribFlags, uint sfgaoMask, out uint psfgaoAttribs);
        void GetCount(out uint pdwNumItems);
        void GetItemAt(uint dwIndex, out IntPtr ppsi);
        void EnumItems(out IntPtr ppenumShellItems);
    }

    const uint SIGDN_FILESYSPATH = 0x80058000;

    static string GetShellItemPath(IntPtr psi) {
        var item = (IShellItem)Marshal.GetObjectForIUnknown(psi);
        IntPtr namePtr;
        item.GetDisplayName(SIGDN_FILESYSPATH, out namePtr);
        string path = Marshal.PtrToStringUni(namePtr);
        Marshal.FreeCoTaskMem(namePtr);
        Marshal.ReleaseComObject(item);
        return path;
    }

    public static string PickFolder(IntPtr owner) {
        IntPtr ppv;
        var clsid = CLSID_FileOpenDialog;
        var iid = IID_IFileOpenDialog;
        CoCreateInstance(ref clsid, IntPtr.Zero, 1, ref iid, out ppv);
        var dlg = (IFileOpenDialog)Marshal.GetObjectForIUnknown(ppv);
        uint opts;
        dlg.GetOptions(out opts);
        dlg.SetOptions(opts | FOS_PICKFOLDERS | FOS_FORCEFILESYSTEM);
        dlg.SetTitle("Select folder with video files");
        int hr = dlg.Show(owner);
        if (hr != 0) { Marshal.ReleaseComObject(dlg); return null; }
        IntPtr psi;
        dlg.GetResult(out psi);
        string path = GetShellItemPath(psi);
        Marshal.Release(psi);
        Marshal.ReleaseComObject(dlg);
        return path;
    }

    public static string[] PickFiles(IntPtr owner) {
        IntPtr ppv;
        var clsid = CLSID_FileOpenDialog;
        var iid = IID_IFileOpenDialog;
        CoCreateInstance(ref clsid, IntPtr.Zero, 1, ref iid, out ppv);
        var dlg = (IFileOpenDialog)Marshal.GetObjectForIUnknown(ppv);
        uint opts;
        dlg.GetOptions(out opts);
        dlg.SetOptions(opts | FOS_ALLOWMULTISELECT | FOS_FORCEFILESYSTEM);
        dlg.SetTitle("Select video files");
        int hr = dlg.Show(owner);
        if (hr != 0) { Marshal.ReleaseComObject(dlg); return null; }
        IntPtr ppenum;
        dlg.GetResults(out ppenum);
        var arr = (IShellItemArray)Marshal.GetObjectForIUnknown(ppenum);
        uint count;
        arr.GetCount(out count);
        string[] result = new string[count];
        for (uint i = 0; i < count; i++) {
            IntPtr psi;
            arr.GetItemAt(i, out psi);
            result[i] = GetShellItemPath(psi);
            Marshal.Release(psi);
        }
        Marshal.Release(ppenum);
        Marshal.ReleaseComObject(dlg);
        return result;
    }
}
'@ -ReferencedAssemblies System.Runtime.InteropServices -ErrorAction Stop -WarningAction SilentlyContinue
    $script:HasModernPicker = $true
} catch {
    $script:HasModernPicker = $false
}

function Show-FolderPicker {
    param([IntPtr]$Owner = [IntPtr]::Zero)
    try { return [ModernPicker]::PickFolder($Owner) } catch {}
    return $null
}

function Show-FilePicker {
    param([IntPtr]$Owner = [IntPtr]::Zero)
    try { return [ModernPicker]::PickFiles($Owner) } catch {}
    return $null
}

# --- FFmpeg detection & install -----------------------------------------------

function Find-FFmpeg {
    $candidates = @()

    try {
        $exeDir = Split-Path -Parent ([Diagnostics.Process]::GetCurrentProcess().MainModule.FileName)
        $candidates += Join-Path $exeDir "ffmpeg.exe"
        $candidates += Join-Path $exeDir "bin\ffmpeg.exe"
    } catch {}
    if ($PSScriptRoot) {
        $candidates += Join-Path $PSScriptRoot "ffmpeg.exe"
        $candidates += Join-Path $PSScriptRoot "bin\ffmpeg.exe"
    }

    $inPath = Get-Command ffmpeg -ErrorAction SilentlyContinue
    if ($inPath) { $candidates += $inPath.Source }

    $wingetBase = "$env:LOCALAPPDATA\Microsoft\WinGet\Packages"
    if (Test-Path $wingetBase) {
        $wg = Get-ChildItem $wingetBase -Filter "ffmpeg.exe" -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($wg) { $candidates += $wg.FullName }
    }

    $appLocal = "$env:LOCALAPPDATA\VideoCompressor\ffmpeg"
    if (Test-Path $appLocal) {
        $al = Get-ChildItem $appLocal -Filter "ffmpeg.exe" -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($al) { $candidates += $al.FullName }
    }

    $candidates += @(
        "C:\Program Files\ffmpeg\bin\ffmpeg.exe",
        "C:\ffmpeg\bin\ffmpeg.exe",
        "$env:USERPROFILE\scoop\shims\ffmpeg.exe",
        "$env:USERPROFILE\AppData\Local\Programs\ffmpeg\bin\ffmpeg.exe"
    )

    $scanRoots = @("C:\", "D:\", "E:\")
    $knownDirs = @(
        "ComfiUi","ComfyUI","pinokio","Blender","DaVinci","Reallusion",
        "obs-studio","HandBrake","kdenlive","Shotcut"
    )
    foreach ($root in $scanRoots) {
        if (-not (Test-Path $root)) { continue }
        foreach ($dir in $knownDirs) {
            $hit = Get-ChildItem "$root*$dir*" -ErrorAction SilentlyContinue |
                   Where-Object { $_.PSIsContainer } | Select-Object -First 1
            if ($hit) {
                $ff = Get-ChildItem $hit.FullName -Filter "ffmpeg.exe" -Recurse -Depth 6 -ErrorAction SilentlyContinue | Select-Object -First 1
                if ($ff) { $candidates += $ff.FullName }
            }
        }
    }

    foreach ($c in $candidates) {
        if ($c -and (Test-Path $c -ErrorAction SilentlyContinue)) { return $c }
    }
    return $null
}

function Install-FFmpegSilently {
    param($LogBox, $StatusLabel, $ProgressBar)

    $wg = Get-Command winget -ErrorAction SilentlyContinue
    if ($wg) {
        Write-Log $LogBox "Installing FFmpeg via winget..." "Orange"
        $StatusLabel.Text = "Installing FFmpeg via winget..."
        [Windows.Forms.Application]::DoEvents()

        $wgProc = Start-Process "winget" `
            -ArgumentList "install Gyan.FFmpeg --silent --accept-package-agreements --accept-source-agreements" `
            -WindowStyle Hidden -PassThru
        while (-not $wgProc.HasExited) {
            [Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 300
        }

        $env:PATH = [Environment]::GetEnvironmentVariable("PATH","Machine") + ";" +
                    [Environment]::GetEnvironmentVariable("PATH","User")

        $found = Find-FFmpeg
        if ($found) { return $found }
        Write-Log $LogBox "winget finished but ffmpeg not found -- downloading directly..." "Orange"
    } else {
        Write-Log $LogBox "winget unavailable -- downloading FFmpeg directly (~80 MB)..." "Orange"
    }

    return Invoke-FFmpegDownload $LogBox $StatusLabel $ProgressBar
}

function Invoke-FFmpegDownload {
    param($LogBox, $StatusLabel, $ProgressBar)

    $destDir = "$env:LOCALAPPDATA\VideoCompressor\ffmpeg"
    $zipPath = "$env:TEMP\ffmpeg_essentials.zip"

    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        $wc = New-Object Net.WebClient

        $script:_dlDone  = $false
        $script:_dlError = $null
        $script:_dlPct   = 0
        $script:_dlMB    = "0"

        $wc.add_DownloadProgressChanged({
            param($s,$e)
            $script:_dlPct = $e.ProgressPercentage
            $script:_dlMB  = [Math]::Round($e.BytesReceived/1MB,1)
        })
        $wc.add_DownloadFileCompleted({
            param($s,$e)
            $script:_dlDone  = $true
            if ($e.Error) { $script:_dlError = $e.Error.Message }
        })

        $ProgressBar.Style   = "Continuous"
        $ProgressBar.Maximum = 100
        $ProgressBar.Value   = 0

        $wc.DownloadFileAsync([Uri]"https://www.gyan.dev/ffmpeg/builds/ffmpeg-release-essentials.zip", $zipPath)

        while (-not $script:_dlDone) {
            $ProgressBar.Value = $script:_dlPct
            $StatusLabel.Text  = "Downloading FFmpeg: $($script:_dlMB) MB  ($($script:_dlPct)%)"
            [Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 150
        }

        $ProgressBar.Value = 100

        if ($script:_dlError) {
            Write-Log $LogBox "Download error: $($script:_dlError)" "Red"
            return $null
        }

        Write-Log $LogBox "Downloaded. Extracting -- may take ~30 sec..." "Orange"
        $StatusLabel.Text = "Extracting FFmpeg..."
        [Windows.Forms.Application]::DoEvents()

        if (Test-Path $destDir) { Remove-Item $destDir -Recurse -Force }
        Add-Type -AssemblyName System.IO.Compression.FileSystem
        [IO.Compression.ZipFile]::ExtractToDirectory($zipPath, $destDir)
        Remove-Item $zipPath -Force

        $ffmpeg = Get-ChildItem $destDir -Filter "ffmpeg.exe" -Recurse | Select-Object -First 1
        if ($ffmpeg) {
            Write-Log $LogBox "FFmpeg ready: $($ffmpeg.FullName)" "LightGreen"
            return $ffmpeg.FullName
        }
    } catch {
        Write-Log $LogBox "Error: $_" "Red"
    }
    return $null
}

# --- Helpers ------------------------------------------------------------------

function Write-Log {
    param($RichBox, $Text, $ColorName = "White")
    $RichBox.SelectionStart  = $RichBox.TextLength
    $RichBox.SelectionLength = 0
    $RichBox.SelectionColor  = [Drawing.Color]::FromName($ColorName)
    $RichBox.AppendText("$Text`n")
    $RichBox.ScrollToCaret()
    [Windows.Forms.Application]::DoEvents()
}

function Get-VideoFiles {
    param($Folder)
    $exts = @("*.mp4","*.mov","*.avi","*.webm","*.mkv","*.mxf","*.m4v","*.wmv")
    $all  = @()
    foreach ($e in $exts) {
        $all += Get-ChildItem -Path $Folder -Filter $e -Recurse -ErrorAction SilentlyContinue |
                Where-Object { $_.FullName -notmatch '\\Compressed\\' }
    }
    return @($all | Sort-Object FullName)
}

function Update-DropZoneDisplay {
    $lstFiles.Items.Clear()
    if ($script:SourceFiles.Count -eq 0) {
        $lblDropHint.Visible = $true
        $lstFiles.Visible = $false
        $lblFileCount.Text = "0 files"
        return
    }
    $lblDropHint.Visible = $false
    $lstFiles.Visible = $true
    foreach ($f in $script:SourceFiles) {
        $lstFiles.Items.Add($f.Name)
    }
    if ($script:SourceFolderRoot) {
        $lblFileCount.Text = "1 folder ($($script:SourceFiles.Count) files)"
    } else {
        $lblFileCount.Text = "$($script:SourceFiles.Count) files"
    }
}

function Get-Duration {
    param($FilePath)
    $out = & $script:FFprobePath -v quiet -show_entries format=duration -of csv=p=0 "$FilePath" 2>&1
    $val = ($out -join "" -replace ',','.').Trim()
    try { return [double]$val } catch { return 10.0 }
}

function Get-AvailableGPUEncoders {
    $script:AvailableGPUEncoders = @{ NVIDIA = $false; AMD = $false; Intel = $false }
    if (-not $script:FFmpegPath) { return }
    try {
        $output = & $script:FFmpegPath -encoders 2>&1 | Out-String
        if ($output -match 'h264_nvenc')  { $script:AvailableGPUEncoders.NVIDIA = $true }
        if ($output -match 'h264_amf')    { $script:AvailableGPUEncoders.AMD    = $true }
        if ($output -match 'h264_qsv')    { $script:AvailableGPUEncoders.Intel  = $true }
    } catch {}
}

function Resolve-GpuMode {
    param([string]$RequestedMode)
    if ($RequestedMode -eq "CPU") { return "CPU" }
    if ($RequestedMode -ne "Auto") {
        if ($script:AvailableGPUEncoders[$RequestedMode]) { return $RequestedMode }
        return "CPU"
    }
    if ($script:AvailableGPUEncoders.NVIDIA) { return "NVIDIA" }
    if ($script:AvailableGPUEncoders.AMD)    { return "AMD" }
    if ($script:AvailableGPUEncoders.Intel)  { return "Intel" }
    return "CPU"
}

function Invoke-FFmpeg {
    param(
        [string[]]$FfmpegArgs,
        [double]$TotalDuration = 0,
        $StatusLabel = $null,
        [string]$PassLabel = "",
        [string]$ProgressFile = "",
        [int]$Threads = 0
    )
    if ($Threads -gt 0) { $FfmpegArgs = @("-threads", "$Threads") + $FfmpegArgs }
    $psi = New-Object Diagnostics.ProcessStartInfo
    $psi.FileName  = $script:FFmpegPath
    $psi.Arguments = ($FfmpegArgs | ForEach-Object { if ($_ -match '\s') { "`"$_`"" } else { $_ } }) -join " "
    $psi.WindowStyle            = [Diagnostics.ProcessWindowStyle]::Hidden
    $psi.UseShellExecute        = $false
    $psi.CreateNoWindow         = $true
    # Do NOT redirect stdout/stderr -- pipe deadlocks corrupt output in PS2EXE.
    # Progress is read from a temp file via -progress <file> instead.
    $psi.RedirectStandardError  = $false
    $psi.RedirectStandardOutput = $false
    $p = [Diagnostics.Process]::Start($psi)
    if ($null -eq $p) { return -1 }
    $script:CurrentFFmpegProc = $p

    $durUs = if ($TotalDuration -gt 0) { [long]($TotalDuration * 1000000) } else { 0 }

    while (-not $p.HasExited) {
        if ($script:CancelRequested) {
            try { $p.Kill() } catch {}
            break
        }

        # Read progress from temp file (written by ffmpeg -progress <file>)
        if ($ProgressFile -and $durUs -gt 0 -and $null -ne $StatusLabel) {
            $tUs = 0
            try {
                $lines = [IO.File]::ReadAllLines($ProgressFile)
                for ($li = $lines.Count - 1; $li -ge 0; $li--) {
                    if ($lines[$li] -match '^out_time_us=(\d+)') {
                        $tUs = [long]$Matches[1]; break
                    }
                }
            } catch {}
            if ($tUs -gt 0) {
                $pct = [Math]::Min(99, [int]($tUs * 100 / $durUs))
                $cur = [TimeSpan]::FromSeconds($tUs / 1000000)
                $tot = [TimeSpan]::FromSeconds($TotalDuration)
                try { $StatusLabel.Text = "$PassLabel   {0:mm\:ss} / {1:mm\:ss}   ({2}%)" -f $cur, $tot, $pct } catch {}
                try {
                    $script:progress.Maximum = 100
                    $script:progress.Value   = $pct
                    $script:progBg.Refresh()
                } catch {}
            } else {
                try { $StatusLabel.Text = "$PassLabel   starting..." } catch {}
            }
        }

        [Windows.Forms.Application]::DoEvents()
        Start-Sleep -Milliseconds 400
    }

    try { $p.WaitForExit() } catch {}
    $code = -1
    try { $code = $p.ExitCode } catch {}
    return $code
}

function Compress-Video {
    param(
        $File, $OutputPath, $MaxSizeMB, $MaxRes, $Format, $LogBox, $StatusLabel = $null,
        [int]$Threads = 0, [string]$Codec = "H.264", [string]$GpuMode = "Auto",
        [string]$ScaleAlgo = "bicubic"
    )

    $duration = Get-Duration $File.FullName
    if ($duration -le 0) { $duration = 10 }

    # Check audio FIRST so we can reserve budget for it before computing video bitrate
    $hasAudio = (& $script:FFprobePath -v quiet -select_streams a:0 `
        -show_entries stream=index -of csv=p=0 "$($File.FullName)" 2>&1) -match '\d'

    $audioBitrateK = if ($hasAudio) { 96 } else { 0 }
    $totalBudgetKB = [int]($MaxSizeMB * 1024 * 0.92)          # 8% container overhead
    $audioBudgetKB = [int]($audioBitrateK * $duration / 8.0)   # KB used by audio track
    $videoBudgetKB = [Math]::Max(50, $totalBudgetKB - $audioBudgetKB)
    $vbrKbps       = [Math]::Max(80, [int]($videoBudgetKB * 8.0 / $duration))

    $scale = "scale='if(gte(iw,ih),$MaxRes,-2)':'if(gte(iw,ih),-2,$MaxRes)':flags=$ScaleAlgo"

    $ext     = switch ($Format) { "MOV" { ".mov" } "WebM" { ".webm" } default { ".mp4" } }
    $outFull = [IO.Path]::ChangeExtension($OutputPath, $ext)
    $outDir  = Split-Path -Parent $outFull
    if (-not (Test-Path $outDir)) { New-Item -ItemType Directory -Path $outDir -Force | Out-Null }

    $isWebM = ($Format -eq "WebM")

    # Resolve GPU mode and select encoder
    $resolvedGpu = Resolve-GpuMode $GpuMode
    $isGpu = ($resolvedGpu -ne "CPU") -and (-not $isWebM)  # libvpx-vp9 has no GPU hw-enc path

    if ($isGpu) {
        $encoderName = switch ($resolvedGpu) {
            "NVIDIA" { if ($Codec -eq "H.265") { "hevc_nvenc" } else { "h264_nvenc" } }
            "AMD"    { if ($Codec -eq "H.265") { "hevc_amf"  } else { "h264_amf"  } }
            "Intel"  { if ($Codec -eq "H.265") { "hevc_qsv"  } else { "h264_qsv"  } }
        }
    } else {
        $encoderName = if ($isWebM) { "libvpx-vp9" } elseif ($Codec -eq "H.265") { "libx265" } else { "libx264" }
    }

    # Use explicit passlogfile in TEMP so we never depend on CWD
    # (PowerShell Set-Location does NOT change Win32 CWD used by child processes)
    $passLog = Join-Path $env:TEMP "ffpass_$([guid]::NewGuid().ToString('N').Substring(0,8))"
    $progressFile = ""

    $audioArgs = if ($hasAudio) {
        if ($isWebM) { @("-c:a","libopus","-b:a","${audioBitrateK}k") }
        else         { @("-c:a","aac","-b:a","${audioBitrateK}k") }
    } else { @("-an") }

    if ($isGpu) {
        # --- GPU path: single-pass with constrained bitrate ---
        $maxrateKbps = [int]($vbrKbps * 1.5)
        $bufsizeKbps = [int]($vbrKbps * 2)

        $vendorFlags = switch ($resolvedGpu) {
            "NVIDIA" { @("-b_ref_mode","0","-maxrate","${maxrateKbps}k","-bufsize","${bufsizeKbps}k") }
            "AMD"    { @("-rc","cbr") }
            "Intel"  { @("-maxrate","${maxrateKbps}k","-bufsize","${bufsizeKbps}k") }
        }

        try {
            $progressFile = Join-Path $env:TEMP "ffprog_$([guid]::NewGuid().ToString('N').Substring(0,8)).txt"
            if ($StatusLabel) { $StatusLabel.Text = "GPU encoding ($resolvedGpu)..." }
            $gpuArgs = @("-y","-progress",$progressFile,"-i",$File.FullName,"-vf",$scale,
                    "-c:v",$encoderName,"-b:v","${vbrKbps}k") + $vendorFlags + $audioArgs +
                   @("-movflags","+faststart",$outFull)
            $exitGpu = Invoke-FFmpeg $gpuArgs -TotalDuration $duration -StatusLabel $StatusLabel -PassLabel "GPU" -ProgressFile $progressFile -Threads $Threads
            if ($exitGpu -eq 0 -or $script:CancelRequested) {
                # GPU succeeded (or user cancelled) -- skip to result check
            } else {
                # GPU failed -- fall back to CPU 2-pass
                Write-Log $LogBox "  [!]  GPU encoding failed, falling back to CPU..." "Orange"
                $isGpu = $false
                $encoderName = if ($Codec -eq "H.265") { "libx265" } else { "libx264" }
                if ($progressFile) { Remove-Item $progressFile -Force -ErrorAction SilentlyContinue }
                $progressFile = ""
            }
        } catch {
            Write-Log $LogBox "  [!]  GPU error: $_ -- falling back to CPU..." "Orange"
            $isGpu = $false
            $encoderName = if ($Codec -eq "H.265") { "libx265" } else { "libx264" }
            if ($progressFile) { Remove-Item $progressFile -Force -ErrorAction SilentlyContinue }
            $progressFile = ""
        }
    }

    if (-not $isGpu -and -not $script:CancelRequested) {
        # --- CPU path: 2-pass encoding ---
        if ($isWebM) {
            $passFlag1   = @("-pass", "1", "-passlogfile", $passLog)
            $passFlag2   = @("-pass", "2", "-passlogfile", $passLog)
            $extraParams = @()
        } elseif ($Codec -eq "H.265") {
            $passFlag1   = @("-x265-params", "pass=1:stats=${passLog}.log")
            $passFlag2   = @("-x265-params", "pass=2:stats=${passLog}.log")
            $extraParams = @()
        } else {
            $passFlag1   = @("-pass", "1", "-passlogfile", $passLog)
            $passFlag2   = @("-pass", "2", "-passlogfile", $passLog)
            $extraParams = @("-x264-params", "mbtree=0")
        }

        # WebM output args: no -movflags (not an MP4 container), no -preset (vp9 uses -quality/-cpu-used)
        $containerArgs = if ($isWebM) {
            @("-quality","good","-cpu-used","2")
        } else {
            @("-preset","slow","-movflags","+faststart")
        }

        try {
            # Pass 1 -- analysis with progress tracking
            $progressFile1 = Join-Path $env:TEMP "ffprog_$([guid]::NewGuid().ToString('N').Substring(0,8)).txt"
            if ($StatusLabel) { $StatusLabel.Text = "Pass 1/2 -- analyzing..." }
            $p1 = @("-y","-progress",$progressFile1,"-i",$File.FullName,"-vf",$scale,
                    "-c:v",$encoderName,"-b:v","${vbrKbps}k") + $extraParams + $passFlag1 +
                   @("-an","-f","null","NUL")
            $exit1 = Invoke-FFmpeg $p1 -TotalDuration $duration -StatusLabel $StatusLabel -PassLabel "Pass 1/2" -ProgressFile $progressFile1 -Threads $Threads
            Remove-Item $progressFile1 -Force -ErrorAction SilentlyContinue
            if ($exit1 -ne 0 -and -not $script:CancelRequested) {
                return @{ Success=$false }
            }

            if ($script:CancelRequested) { return @{ Success=$false } }

            # Pass 2 -- encoding with live progress via temp file (not pipe -- avoids deadlock)
            $progressFile = Join-Path $env:TEMP "ffprog_$([guid]::NewGuid().ToString('N').Substring(0,8)).txt"
            $p2 = @("-y","-progress",$progressFile,"-i",$File.FullName,"-vf",$scale,
                    "-c:v",$encoderName,"-b:v","${vbrKbps}k") + $extraParams + $passFlag2 +
                   $containerArgs + $audioArgs +
                   @($outFull)
            $exit2 = Invoke-FFmpeg $p2 -TotalDuration $duration -StatusLabel $StatusLabel -PassLabel "Pass 2/2" -ProgressFile $progressFile -Threads $Threads
            if ($exit2 -ne 0 -and -not $script:CancelRequested) {
                return @{ Success=$false }
            }
        } finally {
            Remove-Item "${passLog}*" -Force -ErrorAction SilentlyContinue
            if ($progressFile) { Remove-Item $progressFile -Force -ErrorAction SilentlyContinue }
        }
    }

    if (-not $script:CancelRequested -and (Test-Path $outFull)) {
        $kb = [int]((Get-Item $outFull).Length / 1024)
        return @{ Success=$true; SizeKB=$kb; OutPath=$outFull }
    }
    return @{ Success=$false }
}

function Invoke-AudioExtract {
    param(
        $File, [string]$OutputPath, [string]$AudioFormat,
        [int]$AudioBitrateK, $LogBox, $StatusLabel = $null, [int]$Threads = 0
    )
    $duration = Get-Duration $File.FullName

    $hasAudio = (& $script:FFprobePath -v quiet -select_streams a:0 `
        -show_entries stream=index -of csv=p=0 "$($File.FullName)" 2>&1) -match '\d'
    if (-not $hasAudio) {
        Write-Log $LogBox "  No audio track found, skipping." "Orange"
        return @{ Success = $false; Reason = "no-audio" }
    }

    switch ($AudioFormat) {
        "MP3" { $codec = "libmp3lame"; $ext = ".mp3" }
        "AAC" { $codec = "aac";        $ext = ".aac" }
        "WAV" { $codec = "pcm_s16le";  $ext = ".wav" }
    }

    $outFull = [IO.Path]::ChangeExtension($OutputPath, $ext)
    $outDir  = Split-Path -Parent $outFull
    if (-not (Test-Path $outDir)) { New-Item -ItemType Directory -Path $outDir -Force | Out-Null }

    $progressFile = Join-Path $env:TEMP "ffprog_$([guid]::NewGuid().ToString('N').Substring(0,8)).txt"
    try {
        $bitrateArgs = if ($AudioFormat -eq "WAV") { @() } else { @("-b:a", "${AudioBitrateK}k") }
        $ffArgs = @("-y", "-progress", $progressFile, "-i", $File.FullName,
                    "-vn", "-c:a", $codec) + $bitrateArgs + @($outFull)
        $exit = Invoke-FFmpeg $ffArgs -TotalDuration $duration -StatusLabel $StatusLabel `
                    -PassLabel "Extracting audio" -ProgressFile $progressFile -Threads $Threads
        if ($exit -ne 0 -and -not $script:CancelRequested) {
            return @{ Success = $false }
        }
    } finally {
        if ($progressFile) { Remove-Item $progressFile -Force -ErrorAction SilentlyContinue }
    }

    if (-not $script:CancelRequested -and (Test-Path $outFull)) {
        $kb = [int]((Get-Item $outFull).Length / 1024)
        return @{ Success = $true; SizeKB = $kb; OutPath = $outFull }
    }
    return @{ Success = $false }
}

