$btnBrowseFiles.Add_Click({
    $paths = Show-FilePicker $form.Handle
    if ($paths) {
        $script:SourceFolderRoot = $null
        $script:SourceFiles = @()
        foreach ($p in $paths) {
            $ext = [IO.Path]::GetExtension($p).ToLower()
            if ($script:VideoExtensions -contains $ext) {
                $script:SourceFiles += [IO.FileInfo]::new($p)
            }
        }
        Update-DropZoneDisplay
    }
})

$btnBrowseFolder.Add_Click({
    $folder = Show-FolderPicker $form.Handle
    if ($folder -and (Test-Path $folder)) {
        $script:SourceFolderRoot = $folder
        $script:SourceFiles = @(Get-VideoFiles $folder)
        Update-DropZoneDisplay
    }
})

$btnClear.Add_Click({
    $script:SourceFiles = @()
    $script:SourceFolderRoot = $null
    Update-DropZoneDisplay
})

# -- Drag & drop handlers (shared by drop panel and form) ----------------------
$dropDragEnter = {
    param($s, $e)
    if ($e.Data.GetDataPresent([Windows.Forms.DataFormats]::FileDrop)) {
        $e.Effect = [Windows.Forms.DragDropEffects]::Copy
        $dropPanel.BackColor = [Drawing.Color]::FromArgb(20, 40, 20)
    }
}
$dropDragLeave = {
    $dropPanel.BackColor = $clrDropBg
}
$dropDragDrop = {
    param($s, $e)
    $dropPanel.BackColor = $clrDropBg
    $dropped = $e.Data.GetData([Windows.Forms.DataFormats]::FileDrop)
    if (-not $dropped) { return }

    # Single folder dropped?
    if ($dropped.Count -eq 1 -and (Test-Path $dropped[0] -PathType Container)) {
        $script:SourceFolderRoot = $dropped[0]
        $script:SourceFiles = @(Get-VideoFiles $dropped[0])
        Update-DropZoneDisplay
        return
    }

    # Files dropped — filter to video extensions
    $script:SourceFolderRoot = $null
    $script:SourceFiles = @()
    foreach ($p in $dropped) {
        if (Test-Path $p -PathType Leaf) {
            $ext = [IO.Path]::GetExtension($p).ToLower()
            if ($script:VideoExtensions -contains $ext) {
                $script:SourceFiles += [IO.FileInfo]::new($p)
            }
        }
    }
    Update-DropZoneDisplay
}

$dropPanel.Add_DragEnter($dropDragEnter)
$dropPanel.Add_DragLeave($dropDragLeave)
$dropPanel.Add_DragDrop($dropDragDrop)

# Also accept drag on the form itself
$form.AllowDrop = $true
$form.Add_DragEnter($dropDragEnter)
$form.Add_DragLeave($dropDragLeave)
$form.Add_DragDrop($dropDragDrop)

# -- Dashed border on drop panel -----------------------------------------------
$dropPanel.Add_Paint({
    param($s, $e)
    $pen = New-Object Drawing.Pen($clrDropBorder, 1)
    $pen.DashStyle = [Drawing.Drawing2D.DashStyle]::Dash
    $rect = New-Object Drawing.Rectangle(0, 0, ($s.Width - 1), ($s.Height - 1))
    $e.Graphics.DrawRectangle($pen, $rect)
    $pen.Dispose()
})

$form.Add_FormClosing({
    param($s, $e)
    if ($script:IsProcessing) {
        $e.Cancel = $true
        [Windows.Forms.MessageBox]::Show(
            "Processing in progress.`nUse the STOP button first.",
            "Cannot close", "OK", "Warning") | Out-Null
    } else {
        Remove-EmbeddedFontFiles
    }
})

$form.Add_Shown({
    $script:FFmpegPath = Find-FFmpeg

    if ($script:FFmpegPath) {
        $probePath = $script:FFmpegPath -replace "ffmpeg\.exe$","ffprobe.exe"
        if (Test-Path $probePath) {
            $script:FFprobePath = $probePath
        } else {
            Write-Log $logBox "WARNING: ffprobe.exe not found next to ffmpeg.exe" "Orange"
            $script:FFprobePath = $null
        }
        Write-Log $logBox "FFmpeg found: $($script:FFmpegPath)" "LightGreen"
        Get-AvailableGPUEncoders
        $gpuList = @()
        if ($script:AvailableGPUEncoders.NVIDIA) { $gpuList += "NVIDIA" }
        if ($script:AvailableGPUEncoders.AMD)    { $gpuList += "AMD" }
        if ($script:AvailableGPUEncoders.Intel)  { $gpuList += "Intel" }
        if ($gpuList.Count -gt 0) {
            Write-Log $logBox "GPU encoders: $($gpuList -join ', ')" "LightGreen"
        } else {
            Write-Log $logBox "GPU encoders: none detected (CPU only)" "DimGray"
        }
        Write-Log $logBox "Drop files or browse, then click START." "White"
        $lblStatus.Text = "FFmpeg ready"
    } else {
        Write-Log $logBox "FFmpeg not found -- will be installed automatically when you click START." "Orange"
        $lblStatus.Text      = "FFmpeg not found -- will install on Start"
        $lblStatus.ForeColor = [Drawing.Color]::Orange
    }
})

$btnStart.Add_Click({
    # -- STOP mode -------------------------------------------------------------
    if ($btnStart.Tag -eq "stop") {
        $script:CancelRequested = $true
        $btnStart.Text      = "Stopping..."
        $btnStart.BackColor = [Drawing.Color]::FromArgb(120, 30, 30)  # darker danger for stopping
        $btnStart.Enabled   = $false
        return
    }

    # -- START mode ------------------------------------------------------------
    try {
    if ($script:SourceFiles.Count -eq 0) {
        [Windows.Forms.MessageBox]::Show(
            "No source files selected.`nDrop files/folder or use Browse.",
            "Error", "OK", "Error") | Out-Null
        return
    }

    $files  = $script:SourceFiles
    $folder = if ($script:SourceFolderRoot) { $script:SourceFolderRoot }
              else { $files[0].DirectoryName }

    $maxRes    = 0
    $maxSizeMB = 0.0
    $format    = "MP4"

    if ($script:Mode -eq "Video") {
        if (-not [int]::TryParse($txtRes.Text.Trim(), [ref]$maxRes) -or $maxRes -lt 100) {
            [Windows.Forms.MessageBox]::Show("Invalid resolution value.","Error","OK","Error") | Out-Null; return
        }
        if (-not [double]::TryParse($txtSize.Text.Trim().Replace(',','.'),
            [Globalization.NumberStyles]::Any, [Globalization.CultureInfo]::InvariantCulture, [ref]$maxSizeMB) `
            -or $maxSizeMB -le 0) {
            [Windows.Forms.MessageBox]::Show("Invalid file size value.","Error","OK","Error") | Out-Null; return
        }
        $format = if ($rbMOV.Checked) {"MOV"} elseif ($rbWebM.Checked) {"WebM"} else {"MP4"}
    }

    # Audio mode settings
    $audioFormat   = "MP3"
    $audioBitrateK = 192
    if ($script:Mode -eq "Audio") {
        if ($rbAudioAAC.Checked) { $audioFormat = "AAC" }
        elseif ($rbAudioWAV.Checked) { $audioFormat = "WAV" }
        else { $audioFormat = "MP3" }

        if ($rbBr128.Checked) { $audioBitrateK = 128 }
        elseif ($rbBr320.Checked) { $audioBitrateK = 320 }
        else { $audioBitrateK = 192 }
    }

    $outputMode = if ($rbSideBySide.Checked) {"Side"} else {"Compressed"}

    $script:CancelRequested = $false
    $script:IsProcessing    = $true
    $btnStart.Text      = "[X]  STOP"
    $btnStart.BackColor = $clrDanger
    $btnStart.FlatAppearance.MouseOverBackColor = [Drawing.Color]::FromArgb(210, 55, 55)
    $btnStart.FlatAppearance.MouseDownBackColor = [Drawing.Color]::FromArgb(140, 25, 25)

    # Re-wire click to cancel
    $btnStart.Tag = "stop"

    if (-not $script:FFmpegPath) {
        $btnStart.Text  = "Installing FFmpeg..."
        $progress.Style = "Marquee"
        [Windows.Forms.Application]::DoEvents()

        $script:FFmpegPath = Install-FFmpegSilently $logBox $lblStatus $progress

        $progress.Style = "Continuous"
        $btnStart.Text  = "$([char]0x25B6)   C O M P R E S S"

        if (-not $script:FFmpegPath) {
            Write-Log $logBox "ERROR: FFmpeg could not be installed." "Red"
            Write-Log $logBox "Download manually: https://ffmpeg.org/download.html" "OrangeRed"
            $script:IsProcessing = $false
            $btnStart.Text      = "$([char]0x25B6)   C O M P R E S S"
            $btnStart.BackColor = $clrBg
            $btnStart.FlatAppearance.BorderColor = $clrAccent
            $btnStart.FlatAppearance.MouseOverBackColor = [Drawing.Color]::FromArgb(20, 33, 193, 52)
            $btnStart.FlatAppearance.MouseDownBackColor = [Drawing.Color]::FromArgb(40, 33, 193, 52)
            $btnStart.Tag     = "start"
            $btnStart.Enabled = $true
            return
        }
        $probePath2 = $script:FFmpegPath -replace "ffmpeg\.exe$","ffprobe.exe"
        if (Test-Path $probePath2) { $script:FFprobePath = $probePath2 }
        $lblStatus.ForeColor = $clrMuted
        $readyMsg = if ($script:Mode -eq "Audio") { "FFmpeg ready. Starting audio extraction..." } else { "FFmpeg ready. Starting compression..." }
        Write-Log $logBox $readyMsg "LightGreen"
    }

    $progress.Maximum = $files.Count
    $progress.Value   = 0
    $done = 0; $failed = 0

    # -- Pre-flight: warn about files that physically cannot fit (Video only) ----
    if ($script:Mode -eq "Video") {
        $lblStatus.Text = "Analyzing $($files.Count) file(s)..."
        [Windows.Forms.Application]::DoEvents()

        $tooLarge = @()
        foreach ($f in $files) {
            $dur = Get-Duration $f.FullName
            if ($dur -le 0) { $dur = 10 }
            $hasAud = (& $script:FFprobePath -v quiet -select_streams a:0 `
                -show_entries stream=index -of csv=p=0 "$($f.FullName)" 2>&1) -match '\d'
            $aBR   = if ($hasAud) { 96 } else { 0 }
            # Minimum achievable size: 80 kbps video + audio bitrate + 8% container overhead
            $minMB = [Math]::Round((80 + $aBR) * $dur / 8.0 / 1024.0 * 1.08, 2)
            if ($minMB -gt $maxSizeMB) {
                $tooLarge += "  *  $($f.Name)  --  min ~$($minMB) MB  ($([int]$dur)s)"
            }
        }

        if ($tooLarge.Count -gt 0) {
            $warnMsg  = "$($tooLarge.Count) file(s) CANNOT fit within $maxSizeMB MB at minimum quality:`n`n"
            $warnMsg += $tooLarge -join "`n"
            $warnMsg += "`n`nThese files will be compressed as small as possible`nbut will likely exceed your size limit.`n`nContinue anyway?"
            $answer = [Windows.Forms.MessageBox]::Show($warnMsg, "Size Limit Warning", "YesNo", "Warning")
            if ($answer -ne "Yes") {
                $script:IsProcessing = $false
                $btnStart.Text      = "$([char]0x25B6)   C O M P R E S S"
                $btnStart.BackColor = $clrBg
                $btnStart.FlatAppearance.MouseOverBackColor = $clrHover
                $btnStart.FlatAppearance.MouseDownBackColor = $clrPressed
                $btnStart.Tag     = "start"
                $btnStart.Enabled = $true
                $lblStatus.Text   = "Aborted"
                $script:CancelRequested = $false
                return
            }
        }
    }
    # -------------------------------------------------------------------------

    Write-Log $logBox "--------------------------------------" "DimGray"
    Write-Log $logBox "Files      : $($files.Count)" "White"
    if ($script:Mode -eq "Video") {
        $resolvedGpuLog = Resolve-GpuMode $script:GpuMode
        Write-Log $logBox "Resolution : ${maxRes}px   Max size: ${maxSizeMB} MB   Format: $format" "White"
        Write-Log $logBox "Codec      : $($script:Codec)   GPU: $resolvedGpuLog   Scale: $($script:ScaleAlgo)" "White"
    } else {
        Write-Log $logBox "Mode       : Audio extraction   Format: $audioFormat   Bitrate: ${audioBitrateK} kbps" "White"
    }
    Write-Log $logBox "--------------------------------------" "DimGray"

    for ($i = 0; $i -lt $files.Count; $i++) {
        if ($script:CancelRequested) { break }

        $file = $files[$i]
        $num  = $i + 1

        $lblStatus.Text = "[$num / $($files.Count)]  $($file.Name)"
        Write-Log $logBox "[$num/$($files.Count)]  $($file.Name)" "Cyan"
        [Windows.Forms.Application]::DoEvents()

        if ($outputMode -eq "Compressed" -and $script:SourceFolderRoot) {
            $rel        = $file.FullName.Substring($folder.Length).TrimStart('\','/')
            $outputPath = Join-Path $folder "Compressed\$rel"
        } else {
            $base       = [IO.Path]::GetFileNameWithoutExtension($file.Name)
            $suffix     = if ($script:Mode -eq "Audio") { "_audio" } else { "_compressed" }
            $outputPath = Join-Path $file.DirectoryName "${base}${suffix}$([IO.Path]::GetExtension($file.Name))"
        }

        try {
            if ($script:Mode -eq "Audio") {
                $result = Invoke-AudioExtract $file $outputPath $audioFormat $audioBitrateK $logBox $lblStatus -Threads $script:Threads
            } else {
                $result = Compress-Video $file $outputPath $maxSizeMB $maxRes $format $logBox $lblStatus -Threads $script:Threads -Codec $script:Codec -GpuMode $script:GpuMode -ScaleAlgo $script:ScaleAlgo
            }
        } catch {
            $result = @{ Success=$false }
            Write-Log $logBox "  [x]  Exception: $_" "OrangeRed"
        }

        if ($script:CancelRequested) {
            Write-Log $logBox "  [x]  Cancelled" "OrangeRed"
            break
        }

        if ($result.Success) {
            Write-Log $logBox "  [ok]  $($result.SizeKB) KB -> $($result.OutPath)" "LightGreen"
            $done++
        } else {
            if (-not $script:CancelRequested) {
                if ($result.Reason -eq "no-audio") {
                    $failed++  # already logged by Invoke-AudioExtract
                } else {
                    Write-Log $logBox "  [x]  Encoding error" "OrangeRed"
                    $failed++
                }
            } else {
                $failed++
            }
        }

        # Restore bar to file-level tracking after within-file progress
        $progress.Maximum = $files.Count
        $progress.Value   = $num
        [Windows.Forms.Application]::DoEvents()
    }

    Write-Log $logBox "--------------------------------------" "DimGray"
    $summary = if ($script:CancelRequested) { "Cancelled. Done: $done" } else { "Done: $done successful" }
    if ($failed -gt 0) { $summary += ", $failed errors" }
    Write-Log $logBox $summary $(if ($script:CancelRequested) { "Orange" } else { "Yellow" })

    # -- Post-completion actions (sound + open folder) -------------------------
    if (-not $script:CancelRequested -and $done -gt 0) {
        if ($chkSound.Checked) {
            try { [System.Media.SystemSounds]::Asterisk.Play() } catch {}
        }
        if ($chkOpenFolder.Checked) {
            $openPath = if ($outputMode -eq "Compressed" -and $script:SourceFolderRoot) {
                Join-Path $folder "Compressed"
            } else { $folder }
            if (Test-Path $openPath) { Start-Process "explorer.exe" -ArgumentList $openPath }
        }
    }

    # Restore START button
    $script:IsProcessing = $false
    $btnStart.Text      = "$([char]0x25B6)   C O M P R E S S"
    $btnStart.BackColor = $clrBg
    $btnStart.FlatAppearance.BorderColor = $clrAccent
    $btnStart.FlatAppearance.MouseOverBackColor = [Drawing.Color]::FromArgb(20, 33, 193, 52)
    $btnStart.FlatAppearance.MouseDownBackColor = [Drawing.Color]::FromArgb(40, 33, 193, 52)
    $btnStart.Tag     = "start"
    $btnStart.Enabled = $true

    $lblStatus.Text = $summary

    if (-not $script:CancelRequested) {
        $doneDetail = if ($script:Mode -eq "Audio") {
            "$summary`n`nFiles: $($files.Count)  |  Format: $audioFormat  |  Bitrate: ${audioBitrateK} kbps"
        } else {
            "$summary`n`nFiles: $($files.Count)  |  Resolution: ${maxRes}px"
        }
        [Windows.Forms.MessageBox]::Show($doneDetail, "Done", "OK", "Information") | Out-Null
    }

    } catch {
        # Global safety net -- write diagnostics to file since -noConsole hides errors
        $errMsg = "$(Get-Date -f 'HH:mm:ss')  $_`n$($_.ScriptStackTrace)"
        try { [IO.File]::AppendAllText("$env:TEMP\VideoCompressor_error.txt", $errMsg + "`n") } catch {}
        try {
            Write-Log $logBox "CRASH: $_" "Red"
            Write-Log $logBox "Details saved to: $env:TEMP\VideoCompressor_error.txt" "OrangeRed"
        } catch {}
        # Restore button so the app stays usable
        $script:IsProcessing = $false
        try {
            $btnStart.Text      = "$([char]0x25B6)   C O M P R E S S"
            $btnStart.BackColor = $clrBg
            $btnStart.FlatAppearance.BorderColor = $clrAccent
            $btnStart.FlatAppearance.MouseOverBackColor = [Drawing.Color]::FromArgb(20, 33, 193, 52)
            $btnStart.FlatAppearance.MouseDownBackColor = [Drawing.Color]::FromArgb(40, 33, 193, 52)
            $btnStart.Tag     = "start"
            $btnStart.Enabled = $true
            $lblStatus.Text   = "Error -- see log"
        } catch {}
    }
})

# Add logo overlay last (on top of all controls, click-through)
if ($script:LogoPanel) {
    $form.Controls.Add($script:LogoPanel)
    $script:LogoPanel.BringToFront()
}

# Pre-warm shell32 so first Browse click is instant (shell namespace lazy-init)
$warmTimer = New-Object Windows.Forms.Timer
$warmTimer.Interval = 600
$warmTimer.Add_Tick({
    $warmTimer.Stop()
    try { New-Object -ComObject Shell.Application | Out-Null } catch {}
})
$warmTimer.Start()

$form.ShowDialog() | Out-Null
